$pageTitle = 'Settings'; require __DIR__ . '/../includes/header.php';
?><div class="page-content"><div class="detail-heading"><div><span class="eyebrow">Account / Admin settings</span><h2>Profile & settings</h2><p class="muted mb-0">Manage your People & Culture account details.</p></div></div><section class="panel form-card"><?php if ($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" class="stack-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Full name<input name="full_name" value="<?= e($user['full_name']) ?>" required></label><label>Work email<input value="<?= e($user['email']) ?>" disabled></label><label>Phone number<input name="phone" value="<?= e($user['phone']) ?>"></label><label>Role<input value="HR Administrator" disabled></label><button class="btn btn-primary" type="submit">Save changes</button></form></section></div><?php require __DIR__ . '/../includes/footer.php'; ?>
